code='def replace_with_extreme_sum(stack):\n    first=stack.pop()\n    low=high=first\n    while not stack.isEmpty():\n        value=stack.pop()\n        if value < low:\n            low=value\n        if value > high:\n            high=value\n    stack.push(low+high)'
